            <BlockTitle as="h1" size={2} className="max-w-[12ch]">{intro.title}</BlockTitle>
            {intro.lead && <BlockLead>{intro.lead}</BlockLead>}
            <ul data-slot="contact-channels" aria-label="Who answers what">
