const ROW = 36;
const PAD = 4;

function useCoarsePointer() {
  const [coarse, setCoarse] = useState(false);
  useEffect(() => {
    const query = window.matchMedia("(pointer: coarse)");
    const update = () => setCoarse(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);
  return coarse;
}

/**
 * A select whose list opens with the chosen option lying exactly over the
 * trigger text, so the eye never jumps. On touch screens it is the platform
 * picker. A hidden input carries the value in native forms.
 */
export function SelectMenu({
  options,
  value: controlled,
  defaultValue,
  onValueChange,
  placeholder = "Choose…",
  name,
  disabled,
  size = "md",
  variant = "field",
  className,
  ref,
  ...aria
}: {
  options: readonly SelectMenuOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  placeholder?: string;
  /** Submitted with the form. */
  name?: string;
  disabled?: boolean;
  /** sm is 32px for toolbars, filters and table rows; md follows the control height. */
  size?: "sm" | "md";
  /** ghost drops the field ring, for a select inside a composed control (a currency in a money field). */
  variant?: "field" | "ghost";
  className?: string;
  /** The trigger (or, on touch screens, the native select), e.g. for a dialog's first focus. */
  ref?: Ref<HTMLButtonElement | HTMLSelectElement>;
} & Pick<ComponentProps<"button">, "id" | "aria-label" | "aria-labelledby" | "aria-describedby" | "aria-invalid" | "aria-required">) {
  const listId = useId();
  const coarse = useCoarsePointer();
  const [inner, setInner] = useState(defaultValue);
  const value = controlled ?? inner;
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  const [offset, setOffset] = useState(0);
  const trigger = useRef<HTMLButtonElement>(null);
  const list = useRef<HTMLDivElement>(null);
  const selectedIndex = Math.max(0, options.findIndex((option) => option.value === value));
  const selected = options.find((option) => option.value === value);

  // If the change handler moves focus on (e.g. into a reply box), leave it there when the list closes.
  const keepFocus = useRef(false);
  // A form may disable the trigger while it saves the choice. Focus cannot return to a disabled button,
  // so it returns as soon as the trigger is enabled again, unless the reader has moved on by then.
  const refocus = useRef(false);
  useEffect(() => {
    if (disabled || !refocus.current) return;
    refocus.current = false;
    const now = document.activeElement;
    if (!now || now === document.body) trigger.current?.focus();
  }, [disabled]);
  function choose(next: string) {
    if (controlled === undefined) setInner(next);
    onValueChange?.(next);
    const now = document.activeElement;
    keepFocus.current = !!now && now !== document.body && now !== trigger.current && !list.current?.contains(now);
  }

  function openList(nextOpen: boolean) {
    if (nextOpen && trigger.current) {
      // Lay the selected row over the trigger, unless that would leave the viewport.
      const rect = trigger.current.getBoundingClientRect();
      const above = PAD + selectedIndex * ROW;
      const fits = rect.top - above > 8 && rect.top - above + options.length * ROW + PAD * 2 < window.innerHeight - 8;
      setOffset(fits ? -(rect.height + above) - (ROW - rect.height) / 2 : 6);
      setActive(selectedIndex);
    }
    setOpen(nextOpen);
  }

  function move(delta: number) {
    let next = active;
    for (let step = 0; step < options.length; step += 1) {
      next = Math.min(options.length - 1, Math.max(0, next + delta));
      if (!options[next].disabled) break;
    }
    setActive(next);
  }

  function onListKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (event.key === "ArrowDown") move(1);
    else if (event.key === "ArrowUp") move(-1);
    else if (event.key === "Home") setActive(options.findIndex((option) => !option.disabled));
    else if (event.key === "End") setActive(options.length - 1 - [...options].reverse().findIndex((option) => !option.disabled));
    else if (event.key === "Enter" || event.key === " ") {
      const option = options[active];
      if (option && !option.disabled) {
        choose(option.value);
        setOpen(false);
      }
    } else if (event.key === "Tab") setOpen(false);
    else if (/^\S$/.test(event.key)) {
      const start = (active + 1) % options.length;
      const order = [...options.slice(start), ...options.slice(0, start)];
      const hit = order.find((option) => !option.disabled && option.label.toLowerCase().startsWith(event.key.toLowerCase()));
      if (hit) setActive(options.indexOf(hit));
    } else return;
    event.preventDefault();
  }

  useEffect(() => {
    if (!open) return;
    list.current?.querySelector<HTMLElement>(`[data-index="${active}"]`)?.scrollIntoView({ block: "nearest" });
  }, [active, open]);

  if (coarse) {
    return (
      <span data-slot="select-menu-native" data-size={size} data-variant={variant} className={cn("relative block", className)}>
        <select
          ref={ref as Ref<HTMLSelectElement>}
          data-slot="select"
          {...aria}
          name={name}
          disabled={disabled}
          value={value ?? ""}
          onChange={(event) => choose(event.target.value)}
          className={cn(
            "block w-full min-w-0 appearance-none text-base text-foreground outline-none",
            size === "sm" ? "h-8 rounded-control pr-8 pl-2.5" : "h-[var(--control-height)] rounded-button pr-9 pl-3",
          )}
        >
          {!selected && <option value="" disabled>{placeholder}</option>}
          {options.map((option) => (
            <option key={option.value} value={option.value} disabled={option.disabled}>
              {option.label}
              {option.code ? ` · ${option.code}` : ""}
            </option>
          ))}
        </select>
        <ChevronsUpDown aria-hidden="true" className={cn("pointer-events-none absolute top-1/2 size-4 -translate-y-1/2 text-muted-foreground", size === "sm" ? "right-2.5" : "right-3")} />
      </span>
    );
  }

  return (
    <Popover.Root open={open} onOpenChange={openList}>
      <Popover.Trigger asChild>
        <button
          ref={(node) => {
            trigger.current = node;
            if (typeof ref === "function") ref(node);
            else if (ref) (ref as { current: HTMLButtonElement | HTMLSelectElement | null }).current = node;
          }}
          type="button"
          data-slot="select-menu"
          data-size={size}
          data-variant={variant}
          role="combobox"
          aria-haspopup="listbox"
          aria-expanded={open}
          aria-controls={open ? listId : undefined}
          disabled={disabled}
          {...aria}
          onKeyDown={(event) => {
            if (event.key === "ArrowDown" || event.key === "ArrowUp") {
              event.preventDefault();
              openList(true);
            }
          }}
          className={cn(
            "flex w-full min-w-0 items-center justify-between gap-2 text-left text-foreground outline-none disabled:cursor-not-allowed",
            size === "sm" ? "h-8 rounded-control px-2.5 text-[13px]" : "h-[var(--control-height)] rounded-button px-3 text-base md:text-sm",
            className,
          )}
        >
          <span className={cn("flex min-w-0 items-center gap-2", !selected && "text-muted-foreground")}>
            {selected?.icon && <span data-slot="select-menu-icon" aria-hidden="true">{selected.icon}</span>}
            <span className="truncate">{selected ? selected.label : placeholder}</span>
            {selected?.code && <span data-slot="select-menu-code" className="shrink-0">{selected.code}</span>}
          </span>
          <ChevronsUpDown aria-hidden="true" className="size-4 shrink-0 text-muted-foreground" />
        </button>
      </Popover.Trigger>
      {name && <input type="hidden" name={name} value={value ?? ""} />}
      <Popover.Portal>
        <Popover.Content
          side="bottom"
          align="start"
          sideOffset={offset}
          alignOffset={-28}
          avoidCollisions={offset > 0}
          onOpenAutoFocus={(event) => {
            event.preventDefault();
            keepFocus.current = false;
            list.current?.focus();
          }}
          onCloseAutoFocus={(event) => {
            if (keepFocus.current) event.preventDefault();
            else if (trigger.current?.disabled) {
              event.preventDefault();
              refocus.current = true;
            }
          }}
          data-slot="select-menu-content"
          style={{ width: "calc(var(--radix-popover-trigger-width) + 36px)", transformOrigin: `50% ${PAD + selectedIndex * ROW + ROW / 2}px` }}
        >
          <div
            ref={list}
            id={listId}
            role="listbox"
            tabIndex={-1}
            aria-labelledby={aria["aria-labelledby"]}
            aria-label={aria["aria-label"]}
            aria-activedescendant={`${listId}-${active}`}
            onKeyDown={onListKeyDown}
            className="max-h-[calc(8*36px+8px)] overflow-y-auto p-1 outline-none"
          >
            {options.map((option, index) => (
              <div
                key={option.value}
                id={`${listId}-${index}`}
                role="option"
                data-index={index}
                aria-selected={option.value === value}
                aria-disabled={option.disabled || undefined}
                data-active={index === active}
                data-slot="select-menu-option"
                onPointerMove={() => !option.disabled && setActive(index)}
                onClick={() => {
                  if (option.disabled) return;
                  choose(option.value);
                  setOpen(false);
                }}
              >
                <span className="grid size-4 place-items-center">{option.value === value && <Check aria-hidden="true" className="size-4" />}</span>
                {option.icon && <span data-slot="select-menu-icon" aria-hidden="true">{option.icon}</span>}
                <span className="min-w-0 flex-1 truncate">{option.label}</span>
                {option.code && <span data-slot="select-menu-code">{option.code}</span>}
              </div>
            ))}
          </div>
        </Popover.Content>
      </Popover.Portal>
    </Popover.Root>
  );
}

"use client";

import { createContext, useContext, type ReactNode } from "react";

/**
 * True inside a block stage: a frame shown there is a demonstration on a page
 * that already has its own main landmark, so it should not add a second one.
 */
const InStage = createContext(false);

export function StageScope({ children }: { children: ReactNode }) {
  return <InStage.Provider value={true}>{children}</InStage.Provider>;
}

export const useInStage = () => useContext(InStage);

"use client";

import { useEffect, useId, useState, type ComponentProps, type ReactNode } from "react";
import type { BlockAction } from "./block-concept";
import { BlockNav, type BlockNavLink } from "./block-nav";
import { FooterBlock } from "./footer-block";
import { cn } from "./lib/cn";
import "./shared/skip-link.css";
import "./template-page.css";

export type TemplateFooter = Omit<ComponentProps<typeof FooterBlock>, "brand" | "className"> & { brand?: string };

/**
 * The frame every Free page template shares: a skip link, the site header,
 * one main region that can take focus, and the footer block. Pages put
 * their bands inside.
 */
export function TemplatePage({
  brand,
  nav = [],
  signIn,
  primary,
  footer,
  className,
  children,
}: {
  brand: string;
  nav?: readonly BlockNavLink[];
  signIn?: BlockAction;
  primary?: BlockAction;
  footer?: TemplateFooter;
  className?: string;
  children: ReactNode;
}) {
  const id = useId();
  return (
    <div data-slot="block" className={cn("@container relative", className)}>
      <a href={`#${id}-main`} data-slot="skip-link">Skip to content</a>
      <BlockNav brand={brand} nav={nav} signIn={signIn} primary={primary} />
      <main id={`${id}-main`} tabIndex={-1} className="outline-none">
        {children}
      </main>
      {footer && <FooterBlock {...footer} brand={footer.brand ?? brand} />}
    </div>
  );
}

/** The nearest element that scrolls, or null for the window. */
export function scrollParent(element: HTMLElement | null): HTMLElement | null {
  for (let node = element?.parentElement; node; node = node.parentElement) {
    const { overflowY } = getComputedStyle(node);
    if ((overflowY === "auto" || overflowY === "scroll") && node.scrollHeight > node.clientHeight) return node;
  }
  return null;
}

/**
 * Which section the reader is in: the last heading that has passed a line
 * just under the sticky header. Works in the window or a scrolling panel.
 */
export function useScrollSpy(ids: readonly string[], offset = 120) {
  const [active, setActive] = useState(ids[0] ?? "");
  const key = ids.join("|");
  useEffect(() => {
    const first = ids[0] ? document.getElementById(ids[0]) : null;
    if (!first) return;
    const scroller = scrollParent(first);
    const target: HTMLElement | Window = scroller ?? window;
    const update = () => {
      const top = scroller ? scroller.getBoundingClientRect().top : 0;
      let current = ids[0]!;
      for (const id of ids) {
        const element = document.getElementById(id);
        if (element && element.getBoundingClientRect().top - top <= offset) current = id;
      }
      setActive(current);
    };
    update();
    target.addEventListener("scroll", update, { passive: true });
    window.addEventListener("resize", update);
    return () => {
      target.removeEventListener("scroll", update);
      window.removeEventListener("resize", update);
    };
    // ids are compared by value through `key`.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key, offset]);
  return active;
}

/** How far through an element the reader is, 0 to 1. */
export function useReadingProgress(element: HTMLElement | null) {
  const [progress, setProgress] = useState(0);
  useEffect(() => {
    if (!element) return;
    const scroller = scrollParent(element);
    const target: HTMLElement | Window = scroller ?? window;
    const update = () => {
      const rect = element.getBoundingClientRect();
      const top = scroller ? scroller.getBoundingClientRect().top : 0;
      const view = scroller ? scroller.clientHeight : window.innerHeight;
      const travel = rect.height - view;
      setProgress(travel <= 0 ? 1 : Math.min(1, Math.max(0, (top - rect.top) / travel)));
    };
    update();
    target.addEventListener("scroll", update, { passive: true });
    window.addEventListener("resize", update);
    return () => {
      target.removeEventListener("scroll", update);
      window.removeEventListener("resize", update);
    };
  }, [element]);
  return progress;
}

/** Jumps to a section inside whatever scrolls, then moves focus to its heading. */
export function goToSection(id: string) {
  const element = document.getElementById(id);
  if (!element) return;
  const smooth = !window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  element.scrollIntoView({ behavior: smooth ? "smooth" : "auto", block: "start" });
  const heading = element.matches("h1, h2, h3") ? element : element.querySelector<HTMLElement>("h2, h3");
  heading?.setAttribute("tabindex", "-1");
  heading?.focus({ preventScroll: true });
}

/**
 * The page outline: numbered when `numbered`, with the reader's section
 * marked as current. On narrow pages it folds into a disclosure.
 */
export function TemplateOutline({
  items,
  active,
  label = "On this page",
  numbered = false,
  className,
}: {
  items: readonly { id: string; title: string }[];
  active: string;
  label?: string;
  numbered?: boolean;
  className?: string;
}) {
  const list = (
    <ol data-slot="template-outline-list" data-numbered={numbered || undefined}>
      {items.map((item, index) => (
        <li key={item.id}>
          <a
            href={`#${item.id}`}
            aria-current={active === item.id ? "location" : undefined}
            onClick={(event) => {
              event.preventDefault();
              goToSection(item.id);
              history.replaceState(null, "", `#${item.id}`);
            }}
          >
            {numbered && <span data-slot="template-outline-number">{index + 1}.</span>}
            {item.title}
          </a>
        </li>
      ))}
    </ol>
  );
  return (
    <nav aria-label={label} data-slot="template-outline" className={className}>
      <p data-slot="template-outline-label">{label}</p>
      {list}
      <details data-slot="template-outline-fold">
        <summary>{label}</summary>
        {list}
      </details>
    </nav>
  );
}

import type { ComponentProps } from "react";
import { cn } from "./lib/cn";
import "./shared/input-2.css";
import "./textarea.css";

/** A recessed multi-line field that grows with the draft from 3 to 8 lines, then scrolls. */
export function Textarea({ className, ...props }: ComponentProps<"textarea">) {
  return (
    <textarea
      data-slot="textarea"
      className={cn(
        "block min-h-[88px] max-h-[200px] w-full min-w-0 resize-none rounded-button px-3 py-[9px] text-base leading-[22px] text-foreground outline-none [field-sizing:content] placeholder:text-muted-foreground disabled:cursor-not-allowed md:text-sm md:leading-[22px]",
        className,
      )}
      {...props}
    />
  );
}

/* Shared by alert.tsx, toast.tsx; each imports it. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="feedback-message"] {
    display: block;
    animation: caliper-fade-in var(--duration-normal) var(--ease-out);
  }
  :is([data-slot="alert"], [data-slot="toast"])[data-variant="success"]
    [data-slot="feedback-icon"] {
    background: var(--success-subtle);
    color: var(--success);
  }
  :is([data-slot="alert"], [data-slot="toast"])[data-variant="warning"]
    [data-slot="feedback-icon"] {
    background: var(--warning-subtle);
    color: var(--warning);
  }
  :is([data-slot="alert"], [data-slot="toast"])[data-variant="error"]
    [data-slot="feedback-icon"] {
    background: var(--destructive-subtle);
    color: var(--destructive);
  }
  @container (max-width: 22rem) {
    [data-slot="feedback-copy"] {
      display: contents;
    }
    [data-slot="feedback-title"] {
      grid-column: 2;
      grid-row: 1;
      min-width: 0;
      padding-top: 0.25rem;
    }
    [data-slot="feedback-description"],
    [data-slot="feedback-action"] {
      grid-column: 1 / -1;
      margin-top: 0;
    }
    [data-slot="feedback-description"] {
      grid-row: 2;
    }
    [data-slot="feedback-action"] {
      grid-row: 3;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="feedback-message"] {
      animation: none;
    }
  }
}

/* alert.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  [data-slot="alert"] {
    container-type: inline-size;
    opacity: 1;
    transform: translateY(0);
    transition-property: opacity, transform, display;
    transition-duration: var(--duration-normal);
    transition-timing-function: var(--ease-out);
    transition-behavior: allow-discrete;
  }
  [data-slot="alert"][hidden] {
    display: none !important;
    opacity: 0;
    pointer-events: none;
    transition-duration: var(--duration-fast);
  }
  @starting-style {
    [data-slot="alert"]:not([hidden]) {
      opacity: 0;
      transform: translateY(var(--motion-enter-distance));
    }
  }
  @container (max-width: 22rem) {
    [data-slot="alert"] > [data-slot="button"] {
      grid-column: 3;
      grid-row: 1;
    }
  }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="alert"] {
      transition: none;
      transform: none !important;
    }
    @starting-style {
      [data-slot="alert"]:not([hidden]) {
        opacity: 1;
        transform: none;
      }
    }
  }
}

/* block-concept.tsx's styles; it imports this file. Edit freely. */
@layer theme, base, components, utilities;

@layer components {
  /* A site header used outside a block still needs the block tokens. */
  [data-slot="block"] {
    --k-display-font: var(--font-display-block, var(--font-sans, system-ui, sans-serif));
    --k-display-weight: 700;
    --k-display-case: none;
    --k-display-track: -0.03em;
    --k-display-stretch: normal;
    --k-display-lh: 1.04;
    /* Monochrome, from the system tokens, so blocks follow the page theme. */
    --k-bg: var(--background, #fff); --k-surface: var(--elevated, #fff); --k-sunken: var(--surface, #f7f7f8); --k-ink: var(--foreground, #18181b); --k-muted: var(--muted-foreground, #5d5d66); --k-line: var(--border, #e4e4e8);
    --k-line-strong: color-mix(in oklab, var(--border-strong, #8a8a94) 55%, var(--k-line));
    /* The grey second line of a two-tone title; 3:1 or better as large text in both themes. */
    --k-faint: color-mix(in oklab, var(--k-muted) 70%, var(--k-bg));
    --k-accent: var(--k-ink); --k-accent-ink: var(--k-bg); --k-hi: var(--accent-text, var(--k-ink)); --k-hi-soft: var(--accent-soft, var(--k-sunken));
    --k-focus: var(--brand, #bb4400); --k-danger: var(--danger, #c2272d);
    --k-stage: var(--surface, #f7f7f8); --k-stage-dot: color-mix(in oklab, var(--k-ink) 14%, var(--k-stage));
    --k-shadow: none;
    --k-radius: 12px; --k-radius-lg: 16px; --k-radius-xl: 20px; --k-btn-radius: 999px;
    --k-tile-1: color-mix(in oklab, var(--k-ink) 5%, var(--k-bg)); --k-tile-2: color-mix(in oklab, var(--k-ink) 8%, var(--k-bg)); --k-tile-3: color-mix(in oklab, var(--k-ink) 11%, var(--k-bg)); --k-tile-4: color-mix(in oklab, var(--k-ink) 14%, var(--k-bg));
    background: var(--k-bg);
    color: var(--k-ink);
    font-family: var(--font-sans, system-ui, sans-serif);
  }
  /* Band tones inside a concept: a sunken band, or an inverse ink band. */
  [data-slot="block"][data-tone="sunken"] { background: var(--k-sunken); }

  [data-slot="block-inner"] {
    position: relative;
    z-index: 1;
    margin-inline: auto;
    max-inline-size: 1240px;
    padding-inline: clamp(20px, 5cqi, 64px);
    padding-block: clamp(64px, 10cqi, 128px);
  }
  [data-slot="block-inner"][data-width="narrow"] { max-inline-size: 960px; }
  [data-slot="block-inner"][data-width="wide"] { max-inline-size: 1440px; }

  /* ── Type ─────────────────────────────────────────── */
  [data-slot="block-eyebrow"] {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    margin: 0;
    font-size: 14px;
    line-height: 20px;
    font-weight: 500;
    color: var(--k-muted);
  }

  [data-slot="block-title"] {
    margin: 0;
    font-family: var(--k-display-font);
    font-weight: var(--k-display-weight);
    font-stretch: var(--k-display-stretch);
    font-variation-settings: "wdth" var(--k-display-wdth, 100);
    text-transform: var(--k-display-case);
    letter-spacing: var(--k-display-track);
    font-optical-sizing: auto;
    text-wrap: balance;
    color: var(--k-ink);
  }
  [data-slot="block-title"][data-size="1"] { font-size: clamp(40px, 5cqi, 64px); line-height: 1.04; font-weight: 700; letter-spacing: -0.048em; }
  [data-slot="block-title"][data-size="2"] { font-size: clamp(30px, 3.4cqi, 40px); line-height: 1.1; letter-spacing: -0.04em; }
  [data-slot="block-title"][data-size="3"] { font-size: clamp(19px, 1.7cqi, 22px); line-height: 1.2; font-weight: 600; letter-spacing: -0.015em; }
  /* Two-tone titles: the emphasised words land in grey. */
  [data-slot="block-em"] { font-style: normal; color: var(--k-faint); }

  [data-slot="block-lead"] {
    margin: 0;
    max-width: 50ch;
    font-size: clamp(16px, 1.3cqi, 18px);
    line-height: 1.6;
    color: var(--k-muted);
    text-wrap: pretty;
  }

  /* The shared section opening. */
  [data-slot="block-header"] {
    display: grid;
    gap: 20px 48px;
    margin-bottom: clamp(36px, 5cqi, 64px);
  }
  [data-slot="block-header-title"] { display: grid; gap: 18px; justify-items: start; }
  [data-slot="block-header-aside"] { display: grid; gap: 16px; align-content: end; justify-items: start; }
  [data-slot="block-header"][data-align="center"] { justify-items: center; text-align: center; }
