    -webkit-backdrop-filter: blur(var(--blur-overlay, 20px)) saturate(1.2); backdrop-filter: blur(var(--blur-overlay, 20px)) saturate(1.2);
    box-shadow: 0 1px 0 var(--k-line);
  }
  [data-slot="site-menu"][hidden] { display: none; }

  @media (prefers-reduced-motion: reduce) {
    [data-slot="site-header"] { transition: none; }
  }
  @media print {
    [data-slot="site-header"] { display: none !important; }
  }
}

